"use client";

import { useEffect } from "react";
import { useDroneNotifications } from "@/lib/drone/useDroneNotification";
import {
  removeDroneNotification,
} from "@/lib/drone/droneNotificationService";

export default function DroneNotification() {
  const notifications = useDroneNotifications();

  const notification = notifications[0];

  useEffect(() => {
    if (!notification) return;

    const timer = setTimeout(() => {
      removeDroneNotification(notification.id);
    }, 5000);

    return () => clearTimeout(timer);
  }, [notification]);

  if (!notification) {
    return null;
  }

  return (
   <div
  className="
    fixed
    top-20
    right-4
    z-[9999]
    w-[380px]
    max-w-[calc(100vw-2rem)]
    
    sm:top-20
    sm:right-4
    
    max-sm:left-3
    max-sm:right-3
    max-sm:w-auto
  "
>
      <div className="rounded-lg border border-white/10 bg-[#15191f] p-4 shadow-2xl">
        <div className="text-xs font-semibold uppercase tracking-wider text-gray-400">
          {notification.title}
        </div>

        <div className="mt-2 text-sm text-white">
          {notification.message}
        </div>
      </div>
    </div>
  );
}