"use client";

import { useEffect, useState } from "react";

import {
  DroneNotification,
  subscribeToDroneNotifications,
} from "./droneNotificationService";

export function useDroneNotifications() {
  const [notifications, setNotifications] = useState<
    DroneNotification[]
  >([]);

  useEffect(() => {
    const unsubscribe = subscribeToDroneNotifications(
      setNotifications
    );

    return unsubscribe;
  }, []);

  return notifications;
}